{
  "description": "A single quadrupedal creature is shown in right-facing side view against a plain off-white background. The body is low, stout and elongated, with soft, pale pinkish-gray wrinkled skin on the head, throat, belly and limbs, and a dense dorsal covering of overlapping brown scales from the back of the neck to the tip of the tail. The head is large, blunt-snouted and dorsoventrally flattened with small dark eyes on the sides and a closed mouth. Six reddish feathery external gills project from the neck, three per side. Four short thick limbs support the body, each ending in a broad toed foot with small claws. The tail is long, broad and paddle-shaped, pale and smooth ventrally and scaled dorsally, tapering to a rounded tip and extending to the left behind the body.",
  "parts": [
    {
      "part": "head",
      "looks_like": "large, broad, flattened and rounded at the snout, pale pink-gray with darker gray mottling on the crown, small round lateral eyes with black pupils and light gray-blue irises, tiny nostrils at the snout tip, closed mouth with a slight underbite",
      "where": "at the anterior end on the right side of the image, connected to the trunk at the gilled neck"
    },
    {
      "part": "gills",
      "looks_like": "six stalked external gills, three on each side of the neck, each with a thick pinkish base and many fine reddish filamentous branches giving a feathery appearance, arching outward and slightly backward",
      "where": "clustered around the junction of the head and trunk, behind the head on both left and right sides visible in profile"
    },
    {
      "part": "legs",
      "looks_like": "four short, stout, fleshy limbs with deeply wrinkled pale pink-gray skin and visible folds at the joints, muscular and columnar",
      "where": "two forelimbs under the chest and two hindlimbs under the mid-posterior trunk, all four visible in side view splayed slightly outward to support the body"
    },
    {
      "part": "feet",
      "looks_like": "broad fleshy feet with four to five short distinct toes each tipped with a tiny dark claw, wrinkled skin on the dorsal surface",
      "where": "at the distal ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, broad, dorsoventrally flattened and paddle-shaped, pale smooth skin ventrally and covered dorsally with overlapping scales, tapering gradually to a rounded tip, with a low smooth mid-dorsal ridge above the scales",
      "where": "extending posteriorly to the left from the trunk, about half the total body length"
    },
    {
      "part": "scales",
      "looks_like": "numerous large overlapping rounded keratinous scales, brown with lighter highlights and fine concentric striations, arranged in diagonal rows, larger over the mid-back and smaller toward the tail tip",
      "where": "covering the entire dorsal surface from the back of the neck over the back and sides of the trunk and the dorsal surface of the tail"
    },
    {
      "part": "markings",
      "looks_like": "subtle dark gray mottling on the dorsal head, pale transverse wrinkled folds on the throat, belly and limb joints, and fine growth lines on individual scales",
      "where": "on the head crown, ventral trunk, and across the scaled dorsal surface"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
